import {defineComponent,h,computed} from 'vue';
export const YkAIUsage=defineComponent({name:'YkAIUsage',props:{used:{type:Number,default:0},limit:{type:Number,default:32000},label:{type:String,default:'上下文使用量'}},setup(p){const used=computed(()=>Math.max(0,Number.isFinite(p.used)?p.used:0)),limit=computed(()=>Math.max(1,Number.isFinite(p.limit)?p.limit:1)),percent=computed(()=>Math.min(100,Math.round(used.value/limit.value*100)));return()=>h('div',{class:'yk-ai-usage'},[h('div',{},[h('strong',{},p.label),h('span',{},percent.value+'%')]),h('progress',{max:limit.value,value:Math.min(used.value,limit.value),'aria-label':p.label}),h('small',{},`${used.value.toLocaleString()} / ${limit.value.toLocaleString()} tokens`),used.value>limit.value?h('small',{class:'yk-ai-usage__over',role:'status'},'已超过设定上限'):null]);}});
